import React, { useEffect, useState, useRef } from "react";
import { motion, useAnimationFrame } from "framer-motion";

export default function RadarDisplay({
  scanSpeed = 3500, // ms per full rotation
  targetCount = 12,
  radarColor = "#22d3ee",
  alertColor = "#f87171",
}) {
  // Using refs for animation state to prevent constant re-renders
  const [targets, setTargets] = useState([]);
  const angleRef = useRef(0);
  const timeRef = useRef(0);
  const [, setRenderTrigger] = useState(0); // Only used to force visual updates down tree if needed

  useEffect(() => {
    setTargets(
      Array.from({ length: targetCount }, (_, i) => ({
        id: i,
        angle: Math.random() * 360,
        distance: 15 + Math.random() * 65,
        speed: 0.02 + Math.random() * 0.1,
        alert: Math.random() > 0.8,
      }))
    );
  }, [targetCount]);

  useAnimationFrame((time, delta) => {
    timeRef.current += delta;
    angleRef.current = (angleRef.current + (360 * delta) / scanSpeed) % 360;
    // Force a re-render to update target positions and scanline every frame
    setRenderTrigger(prev => prev + 1);
  });

  const polarToXY = (a, d) => {
    const rad = ((a - 90) * Math.PI) / 180;
    return { x: 50 + d * Math.cos(rad), y: 50 + d * Math.sin(rad) };
  };

  const diffAngle = (a) => {
    const diff = Math.abs(angleRef.current - a);
    return Math.min(diff, 360 - diff);
  };

  const DETECTION_WIDTH = 12;

  return (
    <div style={{
      position: 'relative',
      width: '100%',
      maxWidth: '420px',
      margin: '0 auto',
      aspectRatio: '1/1',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    }}>

      {/* Outer Casing / Glow ring */}
      <div style={{
        position: 'absolute', inset: 0,
        borderRadius: '50%',
        background: 'linear-gradient(135deg, rgba(8,17,38,0.6), rgba(4,9,20,0.95))',
        boxShadow: `0 0 60px rgba(34,211,238,0.1), inset 0 0 40px rgba(34,211,238,0.05)`,
        border: '1px solid rgba(34,211,238,0.2)',
      }} />

      {/* Inner radar surface */}
      <div style={{
        position: 'absolute', inset: '12px',
        borderRadius: '50%',
        overflow: 'hidden',
        background: 'radial-gradient(circle at center, rgba(13,26,56,0.5), rgba(4,9,20,0.95))',
        boxShadow: 'inset 0 0 60px rgba(0,0,0,0.8)',
      }}>

        {/* Concentric range rings */}
        {[20, 40, 60, 80].map((r) => (
          <div key={r} style={{
            position: 'absolute',
            borderRadius: '50%',
            border: `1px solid ${radarColor}`,
            opacity: 0.15,
            inset: `${50 - r / 2}%`,
            boxShadow: `0 0 10px ${radarColor}20`
          }} />
        ))}

        {/* Cross-hair lines */}
        {[0, 45, 90, 135].map((deg) => (
          <div key={deg} style={{
            position: 'absolute',
            left: '50%', top: '50%',
            width: '100%', height: '1px',
            background: `linear-gradient(to right, transparent, ${radarColor}40, transparent)`,
            transformOrigin: 'left center',
            transform: `rotate(${deg}deg)`,
          }} />
        ))}

        {/* Targets */}
        {targets.map((t) => {
          const movingAngle = (t.angle + timeRef.current * t.speed * 0.05) % 360;
          const { x, y } = polarToXY(movingAngle, t.distance);
          const detected = diffAngle(movingAngle) < DETECTION_WIDTH;
          const size = detected ? 10 : 4;
          const color = t.alert ? alertColor : radarColor;

          return (
            <div key={t.id} style={{ position: 'absolute', left: `${x}%`, top: `${y}%`, transform: 'translate(-50%,-50%)' }}>
              <motion.div
                initial={false}
                animate={{ 
                  scale: detected ? [1, 1.5, 1] : 1,
                  opacity: detected ? 1 : 0.4
                }}
                transition={{ duration: 0.3 }}
                style={{
                  width: size,
                  height: size,
                  borderRadius: "50%",
                  background: color,
                  boxShadow: `0 0 ${detected ? '20px' : '8px'} ${color}`,
                }}
              />
              {detected && (
                <motion.div
                  initial={{ scale: 1, opacity: 0.8 }}
                  animate={{ scale: 3, opacity: 0 }}
                  transition={{ duration: 1, repeat: Infinity, ease: "easeOut" }}
                  style={{
                    position: "absolute",
                    left: '50%', top: '50%',
                    width: size, height: size,
                    transform: "translate(-50%,-50%)",
                    borderRadius: "50%",
                    border: `2px solid ${color}`,
                  }}
                />
              )}
            </div>
          );
        })}

        {/* Dynamic Sweep Scan line */}
        <div style={{
          position: 'absolute', inset: 0,
          borderRadius: '50%',
          background: `conic-gradient(from ${angleRef.current}deg, ${radarColor}40 0deg, ${radarColor}10 15deg, transparent 45deg, transparent 360deg)`,
          opacity: 0.75,
        }} />

        {/* Center point */}
        <div style={{
          position: 'absolute',
          left: '50%', top: '50%',
          width: '8px', height: '8px',
          background: '#fff',
          borderRadius: '50%',
          transform: 'translate(-50%,-50%)',
          boxShadow: `0 0 20px 4px ${radarColor}`,
        }} />
      </div>

      {/* Dynamic Range Indicator Label */}
      <motion.div 
        animate={{ opacity: [0.4, 0.8, 0.4] }}
        transition={{ duration: 3, repeat: Infinity, ease: "easeInOut" }}
        style={{
          position: 'absolute',
          left: '50%', bottom: '15%',
          transform: 'translateX(-50%)',
          color: radarColor,
          fontSize: '0.65rem',
          fontWeight: 700,
          letterSpacing: '0.15em',
          background: 'rgba(4,9,20,0.6)',
          padding: '2px 8px',
          borderRadius: '4px',
          backdropFilter: 'blur(4px)',
          border: `1px solid ${radarColor}40`
      }}>
        RANGE: 120 NM
      </motion.div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { changePassword } from "../services/authService";
import { useNavigate } from "react-router-dom";
import { useToast } from "../context/ToastContext";

export default function ChangePassword() {
  const navigate = useNavigate();
  const { addToast } = useToast();

  const [form, setForm] = useState({
    old_password: '',
    new_password: '',
    confirm_password: ''
  })
  const [showOld, setShowOld] = useState(false)
  const [showNew, setShowNew] = useState(false)
  const [showConfirm, setShowConfirm] = useState(false)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState('')
  const [loading, setLoading] = useState(false)

  const validatePassword = (password) => {
    const regex =
      /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?#&])[A-Za-z\d@$!%*?#&]{8,}$/;
    return regex.test(password);
  };

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value })
    setError('')
    setSuccess('')
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError('')
    setSuccess('')

    if (form.new_password !== form.confirm_password) {
      setError('New password and confirmation do not match')
      return
    }

    if (!validatePassword(form.new_password)) {
      setError('Password must be 8+ chars and include upper, lower, number & special char')
      return
    }

    setLoading(true)
    try {
      await changePassword({
        old_password: form.old_password,
        new_password: form.new_password,
      });

      addToast("Password changed successfully. Please login again.", "success");
      navigate("/login");
    } catch {
      setError("Old password is incorrect or new password is invalid.");
      addToast("Failed to change password.", "error");
    }
  }

  const renderToggleBtn = (visible, toggleFn, label) => (
    <button
      type="button"
      onClick={toggleFn}
      style={{
        position: 'absolute',
        right: 8,
        top: '50%',
        transform: 'translateY(-50%)',
        background: 'transparent',
        border: 'none',
        cursor: 'pointer',
        width: 28,
        height: 28,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: '#6b7280'
      }}
      aria-label={visible ? `Hide ${label}` : `Show ${label}`}
    >
      {visible ? (
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" width="20" height="20">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.542-7a10.05 10.05 0 013.153-4.278M6.1 6.1L17.9 17.9" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
        </svg>
      ) : (
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" width="20" height="20">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5s8.268 2.943 9.542 7c-1.274 4.057-5.065 7-9.542 7s-8.268-2.943-9.542-7z" />
        </svg>
      )}
    </button>
  )

  return (
    <div className="auth-wrapper">
      <div className="auth-card">
        <div className="auth-card__header">
          <h2 className="auth-card__title">Change Password</h2>
          <p className="auth-card__sub">Update your password to keep your account secure.</p>
        </div>

        <form onSubmit={handleSubmit} style={{ display: 'grid', gap: '1rem' }}>
          <div className="field">
            <label htmlFor="old_password">Current Password</label>
            <div style={{ position: 'relative' }}>
              <input
                id="old_password"
                name="old_password"
                type={showOld ? 'text' : 'password'}
                placeholder="Enter current password"
                value={form.old_password}
                onChange={handleChange}
                required
                autoComplete="current-password"
                style={{ paddingRight: 44 }}
              />
              {renderToggleBtn(showOld, () => setShowOld(s => !s), 'current password')}
            </div>
          </div>

          <div className="field">
            <label htmlFor="new_password">New Password</label>
            <div style={{ position: 'relative' }}>
              <input
                id="new_password"
                name="new_password"
                type={showNew ? 'text' : 'password'}
                placeholder="Enter new password"
                value={form.new_password}
                onChange={handleChange}
                required
                autoComplete="new-password"
                style={{ paddingRight: 44 }}
              />
              {renderToggleBtn(showNew, () => setShowNew(s => !s), 'new password')}
            </div>
          </div>

          <div className="field">
            <label htmlFor="confirm_password">Confirm New Password</label>
            <div style={{ position: 'relative' }}>
              <input
                id="confirm_password"
                name="confirm_password"
                type={showConfirm ? 'text' : 'password'}
                placeholder="Confirm new password"
                value={form.confirm_password}
                onChange={handleChange}
                required
                autoComplete="new-password"
                style={{ paddingRight: 44 }}
              />
              {renderToggleBtn(showConfirm, () => setShowConfirm(s => !s), 'confirmation')}
            </div>
          </div>

          {error && <div className="form-error">{error}</div>}
          {success && <div className="form-success">{success}</div>}

          <button type="submit" className="btn btn--primary btn--full" disabled={loading}>
            {loading ? 'UpdatingΓÇª' : 'Update password ΓåÆ'}
          </button>
        </form>
      </div>
    </div>
  )
}

