                    <div style={{ width: '40px', height: '40px', borderRadius: '50%', border: '2px solid rgba(34,211,238,0.2)', borderTopColor: 'var(--brand-cyan)', animation: 'spin 1s linear infinite', margin: '0 auto 1rem' }} />
