                                        </div>
                                        {ev.details && <p style={{ margin: 0, color: '#fff', fontSize: '0.85rem', lineHeight: 1.4 }}>{ev.details}</p>}
                                        {ev.location && <div style={{ fontSize: '0.75rem', color: 'var(--brand-cyan)', display: 'flex', alignItems: 'center', gap: '0.35rem', marginTop: '0.25rem' }}><MapPin size={12} /> {ev.location}</div>}
                                    </motion.div>
                                ))
                            )}
                        </div>
                    </motion.div>
                </div>

            </div>
        </motion.div>
    );
}

import { useState, useEffect, useCallback, useMemo } from 'react'
import { Link } from 'react-router-dom'
import { fetchVessels, fetchSubscriptions, subscribeVessel, unsubscribeVessel } from '../services/vesselService'
import { useAuthContext } from '../context/AuthContext'
import { useToast } from '../context/ToastContext'
import { motion, AnimatePresence } from 'framer-motion'
import { Search, Filter, Ship, Crosshair, Star, Anchor, ArrowRight, Eye, Radar } from 'lucide-react'

const VESSEL_TYPES = ['', 'Tanker', 'Cargo', 'Container Ship', 'Bulk Carrier', 'Passenger', 'Tug', 'Ferry', 'LNG Carrier', 'Ro-Ro', 'Chemical Tanker', 'Offshore Supply', 'Other']
const CARGO_TYPES = ['', 'Crude Oil', 'Refined Products', 'Chemicals', 'Dry Bulk', 'Containers', 'General Cargo', 'Liquefied Gas', 'Passengers', 'Iron Ore', 'Coal', 'Grain']
const PAGE_SIZE = 50

export default function VesselsPage() {
    const { isAuthenticated } = useAuthContext()
    const { addToast } = useToast()
    const [allVessels, setAllVessels] = useState([])
    const [loading, setLoading] = useState(true)
    const [filters, setFilters] = useState({ name: '', type: '', flag: '', cargo_type: '', destination: '' })
    const [page, setPage] = useState(1)
    const [subscribedIds, setSubscribedIds] = useState(new Set())
    const [togglingId, setTogglingId] = useState(null)

    const loadSubscriptions = useCallback(async () => {
        if (!isAuthenticated) return
        try {
            const subs = await fetchSubscriptions()
            setSubscribedIds(new Set(subs.map(s => s.vessel.id)))
        } catch {
            // silently fail ΓÇö user might not be logged in
        }
    }, [isAuthenticated])

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => { loadVessels(); loadSubscriptions() }, [])

    const loadVessels = async () => {
        setLoading(true)
        try { setAllVessels(await fetchVessels({ page_size: 1000 })) }
        catch (err) { console.error('Failed to load vessels:', err) }
        finally { setLoading(false) }
    }

    // Client-side filtering
    const filtered = useMemo(() => {
        return allVessels.filter(v => {
            if (filters.name && !v.name?.toLowerCase().includes(filters.name.toLowerCase())) return false
            if (filters.type && v.vessel_type !== filters.type) return false
            if (filters.flag && !v.flag?.toLowerCase().includes(filters.flag.toLowerCase())) return false
            if (filters.cargo_type && v.cargo_type !== filters.cargo_type) return false
            if (filters.destination && !v.destination?.toLowerCase().includes(filters.destination.toLowerCase())) return false
            return true
        })
    }, [allVessels, filters])

    const totalPages = Math.ceil(filtered.length / PAGE_SIZE)
    const paginated = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE)

    const handleChange = (e) => {
        setFilters(prev => ({ ...prev, [e.target.name]: e.target.value }))
        setPage(1)
    }
    const handleReset = () => { setFilters({ name: '', type: '', flag: '', cargo_type: '', destination: '' }); setPage(1) }

    const handleToggleSubscription = async (vesselId) => {
        if (!isAuthenticated || togglingId) return
        setTogglingId(vesselId)
        try {
            const isSubscribed = subscribedIds.has(vesselId)
            const vessel = allVessels.find(v => v.id === vesselId)
            const vesselName = vessel ? vessel.name : 'Vessel'
            if (isSubscribed) {
                await unsubscribeVessel(vesselId)
                setSubscribedIds(prev => { const next = new Set(prev); next.delete(vesselId); return next })
                addToast(`Tracking deactivated for ${vesselName}`, 'info')
            } else {
                await subscribeVessel(vesselId)
                setSubscribedIds(prev => new Set([...prev, vesselId]))
                addToast(`Active tracking initiated for ${vesselName}`, 'success')
            }
        } catch (err) {
            console.error('Subscription toggle failed:', err)
            addToast('Uplink failed. Please retry.', 'error')
        } finally {
            setTogglingId(null)
        }
    }

    const containerVariants = {
        hidden: { opacity: 0 },
        show: { opacity: 1, transition: { staggerChildren: 0.05 } }
    }

    const rowVariants = {
        hidden: { opacity: 0, y: 10 },
        show: { opacity: 1, y: 0 }
    }

    return (
        <div style={{ paddingBottom: '3rem' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '2rem', borderBottom: '1px solid var(--border)', paddingBottom: '1.5rem' }}>
                <div>
                    <h1 style={{ fontSize: 'clamp(1.75rem, 3vw, 2.5rem)', fontWeight: 800, color: '#fff', letterSpacing: '-0.02em', fontFamily: '"Space Grotesk", sans-serif', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                        <Radar color="var(--brand-cyan)" size={32} /> Fleet Intelligence Matrix
                    </h1>
                    <p style={{ color: 'var(--text-1)', fontSize: '0.95rem', marginTop: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        {loading ? 'Initializing scan...' : `Scanning ${filtered.length} of ${allVessels.length} registered assets`} &middot; Global maritime registry
                    </p>
                </div>
                <button 
                    onClick={loadVessels} 
                    disabled={loading}
                    style={{ background: 'rgba(34,211,238,0.1)', color: 'var(--brand-cyan)', border: '1px solid rgba(34,211,238,0.3)', padding: '0.5rem 1rem', borderRadius: '8px', cursor: loading ? 'wait' : 'pointer', fontWeight: 600, fontSize: '0.85rem', display: 'flex', alignItems: 'center', gap: '0.5rem', transition: 'all 0.2s' }}
                    onMouseOver={(e) => { if(!loading) e.currentTarget.style.background = 'rgba(34,211,238,0.2)' }}
                    onMouseOut={(e) => { e.currentTarget.style.background = 'rgba(34,211,238,0.1)' }}
                >
                    {loading ? 'Processing...' : 'Recalibrate Scanners'}
                </button>
            </div>

            {/* Glassmorphic Filter Bar */}
            <div style={{ background: 'var(--surface-1)', border: '1px solid var(--border)', borderRadius: '12px', padding: '1rem', marginBottom: '2rem', display: 'flex', flexWrap: 'wrap', gap: '1rem', alignItems: 'center', backdropFilter: 'blur(12px)' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--brand-cyan)', fontWeight: 600, fontSize: '0.85rem', paddingRight: '1rem', borderRight: '1px solid var(--border)' }}>
                    <Filter size={16} /> Filters
                </div>

                <div style={{ position: 'relative', flex: 1, minWidth: '180px' }}>
                    <Search size={14} color="var(--text-2)" style={{ position: 'absolute', left: '10px', top: '50%', transform: 'translateY(-50%)' }} />
                    <input type="text" name="name" placeholder="Vessel Name or ID..." value={filters.name} onChange={handleChange} style={{ width: '100%', background: 'rgba(0,0,0,0.2)', border: '1px solid var(--border-hi)', borderRadius: '6px', padding: '0.55rem 1rem 0.55rem 2rem', color: '#fff', fontSize: '0.85rem', outline: 'none' }} />
                </div>

                <select name="type" value={filters.type} onChange={handleChange} style={{ flex: 1, minWidth: '130px', background: 'rgba(0,0,0,0.2)', border: '1px solid var(--border-hi)', borderRadius: '6px', padding: '0.55rem 1rem', color: '#fff', fontSize: '0.85rem', outline: 'none', appearance: 'none' }}>
                    {VESSEL_TYPES.map(t => <option key={t} value={t} style={{ background: 'var(--bg-1)' }}>{t || 'All Classes'}</option>)}
                </select>

                <input type="text" name="flag" placeholder="Flag (e.g. Panama)" value={filters.flag} onChange={handleChange} style={{ flex: 1, minWidth: '130px', background: 'rgba(0,0,0,0.2)', border: '1px solid var(--border-hi)', borderRadius: '6px', padding: '0.55rem 1rem', color: '#fff', fontSize: '0.85rem', outline: 'none' }} />

                <select name="cargo_type" value={filters.cargo_type} onChange={handleChange} style={{ flex: 1, minWidth: '130px', background: 'rgba(0,0,0,0.2)', border: '1px solid var(--border-hi)', borderRadius: '6px', padding: '0.55rem 1rem', color: '#fff', fontSize: '0.85rem', outline: 'none', appearance: 'none' }}>
                    {CARGO_TYPES.map(c => <option key={c} value={c} style={{ background: 'var(--bg-1)' }}>{c || 'All Cargo'}</option>)}
                </select>

                <input type="text" name="destination" placeholder="Destination port..." value={filters.destination} onChange={handleChange} style={{ flex: 1, minWidth: '130px', background: 'rgba(0,0,0,0.2)', border: '1px solid var(--border-hi)', borderRadius: '6px', padding: '0.55rem 1rem', color: '#fff', fontSize: '0.85rem', outline: 'none' }} />

                {(filters.name || filters.type || filters.flag || filters.cargo_type || filters.destination) && (
                    <button onClick={handleReset} style={{ background: 'transparent', border: '1px solid var(--danger)', color: 'var(--danger)', padding: '0.5rem 1rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem', fontWeight: 600, transition: 'all 0.2s' }}>
                        Clear
                    </button>
                )}
            </div>

            {!isAuthenticated && (
                <div style={{ background: 'rgba(99, 102, 241, 0.1)', border: '1px solid rgba(99, 102, 241, 0.3)', borderRadius: '8px', padding: '1rem', marginBottom: '2rem', color: '#a5b4fc', fontSize: '0.9rem', display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                    <Star size={18} /> <span><Link to="/login" style={{ color: '#fff', fontWeight: 600 }}>Authenticate</Link> your terminal to enable priority vessel tracking.</span>
                </div>
            )}

            {/* Results Data Grid */}
            {loading ? (
                <div style={{ textAlign: 'center', padding: '4rem 0', color: 'var(--brand-cyan)' }}>
                    <div style={{ width: '40px', height: '40px', borderRadius: '50%', border: '2px solid rgba(34,211,238,0.2)', borderTopColor: 'var(--brand-cyan)', animation: 'spin 1s linear infinite', margin: '0 auto 1rem' }} />
                    Decrypting fleet transponders...
                </div>
            ) : filtered.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '4rem 0', color: 'var(--text-2)', background: 'var(--surface-1)', borderRadius: '12px', border: '1px dashed var(--border-hi)' }}>
                    <p style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '1rem' }}>
                        <Anchor size={32} opacity={0.5} />
                        No assets found matching current parameters.
                        <button onClick={handleReset} style={{ background: 'transparent', border: '1px solid var(--border-hi)', color: '#fff', padding: '0.5rem 1.5rem', borderRadius: '6px', cursor: 'pointer' }}>Reset Scanning Matrix</button>
                    </p>
                </div>
            ) : (
                <>
                    <div style={{ overflowX: 'auto', background: 'var(--surface-1)', border: '1px solid var(--border)', borderRadius: '12px', backdropFilter: 'blur(12px)' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '900px' }}>
                            <thead>
                                <tr style={{ borderBottom: '1px solid var(--border)', background: 'rgba(0,0,0,0.2)' }}>
                                    <th style={{ padding: '1rem', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-2)', letterSpacing: '0.05em', textTransform: 'uppercase' }}>Asset</th>
                                    <th style={{ padding: '1rem', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-2)', letterSpacing: '0.05em', textTransform: 'uppercase' }}>Designation</th>
                                    <th style={{ padding: '1rem', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-2)', letterSpacing: '0.05em', textTransform: 'uppercase' }}>Payload</th>
                                    <th style={{ padding: '1rem', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-2)', letterSpacing: '0.05em', textTransform: 'uppercase' }}>Telemetry</th>
                                    <th style={{ padding: '1rem', fontSize: '0.75rem', fontWeight: 600, color: 'var(--text-2)', letterSpacing: '0.05em', textTransform: 'uppercase', textAlign: 'right' }}>Directives</th>
                                </tr>
                            </thead>
                            <motion.tbody variants={containerVariants} initial="hidden" animate="show">
                                {paginated.map((v) => {
                                    const isSubscribed = subscribedIds.has(v.id)
                                    const isToggling = togglingId === v.id
                                    return (
                                        <motion.tr 
                                            variants={rowVariants}
                                            key={v.id} 
                                            style={{ borderBottom: '1px solid rgba(255,255,255,0.05)', transition: 'background 0.2s', background: isSubscribed ? 'rgba(34,211,238,0.03)' : 'transparent' }}
                                            onMouseOver={(e) => { e.currentTarget.style.background = 'rgba(255,255,255,0.04)' }}
                                            onMouseOut={(e) => { e.currentTarget.style.background = isSubscribed ? 'rgba(34,211,238,0.03)' : 'transparent' }}
                                        >
                                            <td style={{ padding: '1rem' }}>
                                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                                                    <div style={{ width: '32px', height: '32px', borderRadius: '8px', background: 'rgba(255,255,255,0.05)', display: 'grid', placeItems: 'center', color: 'var(--brand-cyan)' }}>
                                                        <Ship size={16} />
                                                    </div>
                                                    <div>
                                                        <div style={{ fontWeight: 600, color: '#fff', fontSize: '0.9rem' }}>{v.name}</div>
                                                        <div style={{ fontSize: '0.7rem', color: 'var(--text-2)', fontFamily: 'monospace' }}>IMO: {v.imo_number} | {v.flag}</div>
                                                    </div>
                                                </div>
                                            </td>
                                            <td style={{ padding: '1rem' }}>
                                                <span style={{ display: 'inline-block', padding: '0.25rem 0.6rem', background: 'rgba(139, 92, 246, 0.15)', color: '#c4b5fd', border: '1px solid rgba(139, 92, 246, 0.3)', borderRadius: '6px', fontSize: '0.75rem', fontWeight: 500 }}>
                                                    {v.vessel_type}
                                                </span>
                                            </td>
                                            <td style={{ padding: '1rem' }}>
                                                <div style={{ fontSize: '0.85rem', color: 'var(--text-1)' }}>{v.cargo_type}</div>
                                            </td>
                                            <td style={{ padding: '1rem' }}>
                                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--text-1)', fontSize: '0.8rem', fontFamily: 'monospace' }}>
                                                    <Crosshair size={14} color="var(--brand-primary)" />
                                                    {v.last_position_lat != null
                                                        ? `${Number(v.last_position_lat).toFixed(4)}, ${Number(v.last_position_lon).toFixed(4)}`
                                                        : <span style={{ opacity: 0.5 }}>OFFLINE</span>}
                                                </div>
                                            </td>
                                            <td style={{ padding: '1rem', textAlign: 'right' }}>
                                                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '0.5rem' }}>
                                                    {isAuthenticated && (
                                                        <button
                                                            onClick={() => handleToggleSubscription(v.id)}
                                                            disabled={isToggling}
                                                            style={{ 
                                                                background: isSubscribed ? 'rgba(34,211,238,0.1)' : 'transparent', 
                                                                color: isSubscribed ? 'var(--brand-cyan)' : 'var(--text-2)', 
                                                                border: isSubscribed ? '1px solid rgba(34,211,238,0.3)' : '1px solid var(--border-hi)', 
                                                                padding: '0.4rem 0.75rem', borderRadius: '6px', cursor: isToggling ? 'wait' : 'pointer', fontSize: '0.75rem', fontWeight: 600, display: 'flex', alignItems: 'center', gap: '0.35rem', transition: 'all 0.2s'
                                                            }}
                                                        >
                                                            <Star size={14} fill={isSubscribed ? 'var(--brand-cyan)' : 'transparent'} /> {isSubscribed ? 'TRACKING' : 'TRACK'}
                                                        </button>
                                                    )}
                                                    <Link to={`/vessels/${v.id}`} style={{ textDecoration: 'none' }}>
                                                        <button style={{ background: 'var(--brand-grad)', color: '#000', border: 'none', padding: '0.4rem 0.75rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.75rem', fontWeight: 700, display: 'flex', alignItems: 'center', gap: '0.35rem', boxShadow: '0 0 10px rgba(34,211,238,0.3)' }}>
                                                            <Eye size={14} /> VIEW
                                                        </button>
                                                    </Link>
                                                </div>
                                            </td>
                                        </motion.tr>
                                    )
                                })}
                            </motion.tbody>
                        </table>
                    </div>

                    {/* Matrix Pagination Controls */}
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '1.5rem', padding: '0 0.5rem' }}>
                        <span style={{ color: 'var(--text-2)', fontSize: '0.8rem', fontFamily: 'monospace' }}>
                            DISPLAYING {(page - 1) * PAGE_SIZE + 1} TO {Math.min(page * PAGE_SIZE, filtered.length)} OF {filtered.length} ASSETS
                        </span>
                        {totalPages > 1 && (
                            <div style={{ display: 'flex', gap: '0.25rem' }}>
                                <button style={{ background: 'var(--surface-1)', border: '1px solid var(--border)', color: 'var(--text-1)', padding: '0.4rem 0.8rem', borderRadius: '6px', cursor: page === 1 ? 'not-allowed' : 'pointer', opacity: page === 1 ? 0.5 : 1 }} onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}>PREV</button>

                                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                                    let p = page <= 3 ? i + 1 : page >= totalPages - 2 ? totalPages - 4 + i : page - 2 + i;
                                    if(p < 1) p = 1;
                                    if(p > totalPages) p = totalPages;
                                    return (
                                        <button key={p} 
                                            style={{ 
                                                background: page === p ? 'rgba(34,211,238,0.15)' : 'var(--surface-1)', 
                                                border: page === p ? '1px solid var(--brand-cyan)' : '1px solid var(--border)', 
                                                color: page === p ? 'var(--brand-cyan)' : 'var(--text-1)', 
                                                padding: '0.4rem 0.8rem', borderRadius: '6px', cursor: 'pointer', fontWeight: page === p ? 700 : 400 
                                            }}
                                            onClick={() => setPage(p)}
                                        >{p}</button>
                                    )
                                })}

                                <button style={{ background: 'var(--surface-1)', border: '1px solid var(--border)', color: 'var(--text-1)', padding: '0.4rem 0.8rem', borderRadius: '6px', cursor: page === totalPages ? 'not-allowed' : 'pointer', opacity: page === totalPages ? 0.5 : 1 }} onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}>NEXT</button>
                            </div>
                        )}
                    </div>
                </>
            )}
        </div>
    )
}
